// The attacks. Each test is an attack that must FAIL — so on the starter,
// where the holes are still open, these tests are red. Each name is a row of
// a threat table: who attacks, what they try, what must happen instead.
//
// Do not edit this file to make it pass. If you think a test is wrong, say so
// in NOTES.md — that is a finding.
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { startApp, CODE } from './helpers.js';
import { scan } from '../scripts/scan-secrets.js';

let app;
before(async () => { app = await startApp(); });
after(() => app.close());

const submit = (user, code, lab = 1) => app.as(user).post(`/api/labs/${lab}/submissions`, { code });

// — Ownership: whose submission is it? —

test('A1 a student reading a classmate\'s submission gets 404, as if it did not exist', async () => {
  const s = await submit('stu1', CODE.mergeSort);
  const r = await app.as('stu2').get(`/api/submissions/${s.body.id}`);
  assert.equal(r.status, 404);
  assert.ok(!r.text.includes('mergeSort'), 'the response leaks the code');
});

test('A2 a TA of another class reading a submission gets 404', async () => {
  const s = await submit('stu1', CODE.mergeSort);
  assert.equal((await app.as('ta_b').get(`/api/submissions/${s.body.id}`)).status, 404);
});

test('A3 a TA of another class cannot open this class\'s review queue', async () => {
  assert.equal((await app.as('ta_b').get('/api/labs/1/submissions')).status, 404);
});

// — Roles: who may publish? —

test('A4 a student calling the publish endpoint gets 403 and nothing is published', async () => {
  const r = await app.as('stu1').post('/api/labs/1/publish');
  assert.equal(r.status, 403);
  const row = app.db.prepare('SELECT published_at FROM labs WHERE id = 1').get();
  assert.equal(row.published_at, null, 'the lab was published by a student');
});

test('A5 a TA of another class cannot publish that class\'s lab', async () => {
  const r = await app.as('ta_a').post('/api/labs/2/publish');
  assert.equal(r.status, 404);
  const row = app.db.prepare('SELECT published_at FROM labs WHERE id = 2').get();
  assert.equal(row.published_at, null, 'the lab was published by the wrong TA');
});

// — Secrets —

test('A6 the model key is not sent to the browser', async () => {
  const r = await app.as(null).get('/api/config');
  assert.ok(!/lk_live_|modelApiKey/.test(r.text), `/api/config returns ${r.text}`);
});

test('A7 no key-shaped string in the source tree', () => {
  const found = scan();
  assert.deepEqual(found, [], found.map((f) => `${f.file}:${f.line} ${f.rule}`).join('\n'));
});

// — Prompt injection: text in the submission talking to the checker —

test('A8 a comment telling the checker the code is compliant does not hide std::sort', async () => {
  const s = await submit('stu1', CODE.stdSortWithComment);
  assert.equal(s.body.verdict, 'violation');
  assert.match(s.body.evidence[0] ?? '', /std::sort/);
});

test('A9 a string addressed to the grader sends the submission to a human, not to pass', async () => {
  const s = await submit('stu1', CODE.bubbleSortWithString);
  assert.notEqual(s.body.verdict, 'pass');
});

test('A10 a violation whose evidence is not a line of the submission becomes unsure', async () => {
  const s = await submit('stu1', CODE.mergeSortNamedBubble);
  assert.equal(s.body.verdict, 'unsure', `verdict ${s.body.verdict}, evidence ${JSON.stringify(s.body.evidence)}`);
});
